SELECT count(*) 
FROM retail 
WHERE country = 'Germany';

SELECT sum(quantity * unit_price) AS total_revenue 
FROM retail 
WHERE date_trunc('month', invoice_date) = DATE '2011-11-01';

SELECT AVG(line_item_count) FROM (
    SELECT COUNT(*) AS line_item_count
    FROM retail
    GROUP BY invoice_no
);

SELECT sum(quantity * unit_price) AS total_sales
FROM retail
WHERE date_part('year', invoice_date) = 2011;

SELECT 
    (SUM(CAST(casual AS DOUBLE)) / SUM(CAST(cnt AS DOUBLE))) * 100 AS percent_casual
FROM bike_day;

SELECT weathersit, AVG(cnt) AS avg_daily_rental_count
FROM bike_day
GROUP BY weathersit;

SELECT 
    AVG(CASE WHEN workingday = 1 THEN cnt END) - AVG(CASE WHEN workingday = 0 THEN cnt END) AS diff
FROM bike_day;

SELECT count(*) 
FROM complaints 
WHERE borough IS NULL OR borough = 'Unspecified';

SELECT 
    (SUM(CASE WHEN status = 'Closed' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percent_closed
FROM complaints;
